class Solution {
  private int build(int first, int second) {
    int level = 1, usedFirst = 0, usedSecond = 0;
    while (true) {
      if ((level & 1) == 1) {
        if (usedFirst + level > first) break;
        usedFirst += level;
      } else {
        if (usedSecond + level > second) break;
        usedSecond += level;
      }
      level++;
    }
    return level - 1;
  }

  public int maxHeightOfTriangle(int red, int blue) {
    return Math.max(build(red, blue), build(blue, red));
  }
}
